LOT = json.loads(LOT_JSON)
NODES: dict[str, tuple[float, float]] = {k: tuple(v) for k, v in LOT["nodes"].items()}
EDGES: list[tuple[str, str]] = [tuple(e) for e in LOT["edges"]]
SLOTS: dict[str, dict] = LOT["slots"]
GATE: tuple[float, float] = tuple(LOT["gate"])
ENTRY: str = LOT["entry"]
EXIT: str = LOT["exit"]


def dist(p: tuple[float, float], q: tuple[float, float]) -> float:
    """두 점 사이 유클리드 거리. 벡터 (q - p) 의 크기입니다."""
    return math.hypot(q[0] - p[0], q[1] - p[1])


# ══════════════════════════════════════════════════════════════════════
# 1. 그래프 G = (V, E)
# ══════════════════════════════════════════════════════════════════════
#
# V = 통로 위의 점들 (71개),  E = 갈 수 있는 방향 (80개)
#
# 간선에 붙은 가중치 w(u, v) 는 두 점 사이 거리입니다.
# "가중 방향 그래프(weighted directed graph)" 라고 부릅니다.


def adjacency_list() -> dict[str, list[tuple[str, float]]]:
    """인접 리스트:  u -> [(v, w(u,v)), ...]

    그래프를 컴퓨터에 담는 가장 흔한 방법입니다. 간선이 적을 때(희소 그래프)
    메모리를 아낍니다. 우리 그래프는 노드 71개에 간선 80개뿐이니 아주 희소합니다.
    """
    adj: dict[str, list[tuple[str, float]]] = {u: [] for u in NODES}
    for u, v in EDGES:
        adj[u].append((v, dist(NODES[u], NODES[v])))
    return adj


def adjacency_matrix() -> tuple[list[str], list[list[float]]]:
    """인접 행렬 A:  A[i][j] = w(i, j),  길이 없으면 무한대

    ── 여기가 선형대수와 만나는 지점입니다 ──

    A 를 0/1 행렬 B (길이 있으면 1) 로 두면 다음이 성립합니다:

        (B^k)[i][j] = i 에서 j 로 가는 **길이 k 짜리 경로의 개수**

    행렬 곱 한 번이 "한 걸음 더 가기" 에 해당합니다. 이 성질이
    최단경로·연결성·중심성 같은 그래프 성질을 선형대수로 다루는 출발점입니다.
    """
    ids = sorted(NODES)
    idx = {u: i for i, u in enumerate(ids)}
    n = len(ids)
    A = [[math.inf] * n for _ in range(n)]
    for i in range(n):
        A[i][i] = 0.0
    for u, v in EDGES:
        A[idx[u]][idx[v]] = dist(NODES[u], NODES[v])
    return ids, A


def reachable_count(src: str) -> int:
    """src 에서 갈 수 있는 노드 수. 일방통행 때문에 전부는 아닐 수 있습니다."""
    adj = adjacency_list()
    seen = {src}
    stack = [src]
    while stack:
        u = stack.pop()
        for v, _ in adj[u]:
            if v not in seen:
                seen.add(v)
                stack.append(v)
    return len(seen)


