# 2. 최단경로 — 다익스트라
# ══════════════════════════════════════════════════════════════════════
#
# "입구에서 이 주차면까지 얼마나 멀까?" 를 푸는 알고리즘입니다.
# 간선 가중치가 모두 0 이상일 때 쓸 수 있고, 시간복잡도는 O(E log V) 입니다.
#
# 핵심 아이디어: 아직 확정 안 된 점들 중 **가장 가까운 것부터** 확정한다.
# 한 번 확정된 점의 거리는 다시 줄어들지 않는다 (가중치가 음수가 아니므로).


def dijkstra(src: str) -> tuple[dict[str, float], dict[str, str]]:
    """src 에서 모든 노드까지의 최단거리와 직전 노드를 돌려줍니다."""
    adj = adjacency_list()
    d: dict[str, float] = {src: 0.0}
    prev: dict[str, str] = {}
    pq: list[tuple[float, str]] = [(0.0, src)]
    done: set[str] = set()

    while pq:
        du, u = heappop(pq)
        if u in done:
            continue
        done.add(u)
        for v, w in adj[u]:
            nd = du + w
            if nd < d.get(v, math.inf):     # 더 짧은 길을 찾았다 (완화, relaxation)
                d[v] = nd
                prev[v] = u
                heappush(pq, (nd, v))
    return d, prev


def path_of(prev: dict[str, str], src: str, dst: str) -> list[str] | None:
    """직전 노드 표를 거꾸로 따라가 경로를 복원합니다."""
    if dst != src and dst not in prev:
        return None
    path = [dst]
    while path[-1] != src:
        path.append(prev[path[-1]])
    path.reverse()
    return path


# ══════════════════════════════════════════════════════════════════════
# 3. 비용 행렬 C
# ══════════════════════════════════════════════════════════════════════
#
#   c(i, j) = w1 * (차량 i 가 주차면 j 까지 달릴 거리)
#           + w4 * (주차면 j 에서 건물까지 걸을 거리)
#
# 실제 시뮬레이터는 회전수·혼잡도·차종제약 항이 더 있지만, 여기서는 문제의
# 뼈대만 남겼습니다.
#
# ★ 왜 항을 더해서(가산적으로) 만드나?
#   그래야 배정 문제가 **선형** 이 되고, 헝가리안 같은 다항시간 알고리즘이 통합니다.
#   현실은 선형이 아닙니다 (혼잡은 특히). 그 간극이 이 연구의 주제 중 하나입니다.

W_DRIVE = 1.0   # 타고 가는 1 m
W_WALK = 1.8    # 걸어가는 1 m — 걷는 게 더 싫으니 가중치가 더 큽니다


def drive_distances(from_node: str = ENTRY) -> dict[str, float]:
    """입구에서 각 주차면까지 실제로 달려야 하는 거리."""
    d, _ = dijkstra(from_node)
    out = {}
    for sid, s in SLOTS.items():
        if s["a"] in d:
            out[sid] = d[s["a"]] + 3.0      # 통로에서 주차면으로 꺾어 들어가는 몫
    return out


def walk_distances() -> dict[str, float]:
    """주차면에서 건물 출입구까지 걸어갈 거리 (직선)."""
    return {sid: dist(tuple(s["c"]), GATE) for sid, s in SLOTS.items()}


def cost_matrix(car_nodes: list[str], free_slots: list[str]) -> list[list[float]]:
    """C[i][j] = 지금 car_nodes[i] 에 있는 차량에게 주차면 j 를 줬을 때의 비용.

    **차량마다 현재 위치가 다르다는 점이 중요합니다.** 모두 입구에 있으면 행이
    전부 같아져 문제가 퇴화(degenerate)하고, 어떤 배정을 해도 총비용이 같습니다.
    실제로는 재배정이 통로 한복판에서 일어나므로 차량들이 흩어져 있습니다.
    """
    walk = walk_distances()
    rows = []
    for node in car_nodes:
        drive = drive_distances(node)
        rows.append(
            [W_DRIVE * drive.get(j, 1e9) + W_WALK * walk[j] for j in free_slots]
        )
    return rows


# ══════════════════════════════════════════════════════════════════════
# 4. 배정 문제 (Assignment Problem)
# ══════════════════════════════════════════════════════════════════════
#
#   결정변수  x_ij ∈ {0, 1}      차량 i 에게 주차면 j 를 주면 1
#
#   최소화    Σ_i Σ_j  c_ij * x_ij
#   제약      Σ_j x_ij = 1   (차량마다 자리 하나)
#             Σ_i x_ij ≤ 1   (자리마다 차량 하나)
#
# 0/1 변수라 정수계획처럼 보이지만, 이 문제는 **제약행렬이 완전 유니모듈러**라
# 실수로 풀어도 답이 정수로 나옵니다. 그래서 어렵지 않고 다항시간에 풀립니다.
# (이 사실이 왜 성립하는지가 교수님께 물어볼 좋은 질문입니다.)


def greedy_assign(C: list[list[float]]) -> tuple[list[int], float]:
    """탐욕법: 차량을 순서대로 보며 그때그때 가장 싼 빈 자리를 준다.

    빠르고 단순하지만 **전체로 보면 최적이 아닐 수 있습니다.**
    앞 차량이 뒤 차량에게 꼭 필요했던 자리를 가져가 버리기 때문입니다.
    """
    n, m = len(C), len(C[0])
    used = [False] * m
    pick = [-1] * n
    total = 0.0
    for i in range(n):
        best, bj = math.inf, -1
        for j in range(m):
            if not used[j] and C[i][j] < best:
                best, bj = C[i][j], j
        if bj >= 0:
            used[bj] = True
            pick[i] = bj
            total += best
    return pick, total


def hungarian(C: list[list[float]]) -> tuple[list[int], float]:
    """헝가리안 알고리즘 (Jonker-Volgenant 형태). 총비용 **최소**를 보장합니다.

    시간복잡도 O(n^2 m). 아이디어는 '최소비용 증가경로를 반복해서 찾기' 입니다.
    선형계획의 쌍대(dual) 변수 u, v 를 유지하면서 c_ij - u_i - v_j >= 0 을
    지키는 것이 핵심인데, 그 이유를 이해하는 것이 조합최적화 공부의 관문입니다.

    지금은 '답이 맞다는 것' 만 확인하고, 원리는 나중에 보셔도 됩니다.
    """
    n, m = len(C), len(C[0])
    assert n <= m, "차량 수가 자리 수보다 많으면 안 됩니다"

    INF = math.inf
    u = [0.0] * (n + 1)          # 행(차량)의 쌍대 변수
    v = [0.0] * (m + 1)          # 열(자리)의 쌍대 변수
    p = [0] * (m + 1)            # 열 j 에 배정된 행
    way = [0] * (m + 1)

    for i in range(1, n + 1):
        p[0] = i
        j0 = 0
        minv = [INF] * (m + 1)
        used = [False] * (m + 1)
        while True:
            used[j0] = True
            i0, delta, j1 = p[j0], INF, 0
            for j in range(1, m + 1):
                if used[j]:
                    continue
                cur = C[i0 - 1][j - 1] - u[i0] - v[j]
                if cur < minv[j]:
                    minv[j], way[j] = cur, j0
                if minv[j] < delta:
                    delta, j1 = minv[j], j
            for j in range(m + 1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while j0:
            j1 = way[j0]
            p[j0], j0 = p[j1], j1

    pick = [-1] * n
    total = 0.0
    for j in range(1, m + 1):
        if p[j] > 0:
            pick[p[j] - 1] = j - 1
            total += C[p[j] - 1][j - 1]
    return pick, total


# ══════════════════════════════════════════════════════════════════════
# 5. 혼잡 — 배정이 통로 부하를 바꾼다
# ══════════════════════════════════════════════════════════════════════
#
# 배정을 정하면 경로가 정해지고, 경로가 정해지면 어느 통로에 차가 몰릴지가
# 정해집니다. **배정 알고리즘은 사실 교통 배분 알고리즘이기도 합니다.**


def edge_load(routes: list[list[str]]) -> dict[tuple[str, str], int]:
    """각 간선을 몇 대가 지나는가."""
    load: dict[tuple[str, str], int] = {}
    for path in routes:
        for a, b in zip(path, path[1:]):
            load[(a, b)] = load.get((a, b), 0) + 1
    return load


def load_stats(load: dict[tuple[str, str], int]) -> dict[str, float]:
    """부하가 고르게 퍼졌는지, 한 곳에 몰렸는지."""
    if not load:
        return {"max": 0, "mean": 0.0, "edges": 0}
    vals = list(load.values())
    return {
        "max": max(vals),                       # 가장 붐비는 간선의 대수 = 병목
        "mean": sum(vals) / len(vals),
        "edges": len(vals),
    }


# ══════════════════════════════════════════════════════════════════════
# 6. 실행
# ══════════════════════════════════════════════════════════════════════


def main() -> None:
    line = "=" * 66

    print(line)
    print(" 1. 그래프 G = (V, E)")
    print(line)
    ids, A = adjacency_matrix()
    n_inf = sum(1 for row in A for x in row if math.isinf(x))
    print(f"  |V| = {len(NODES)} 개 노드,  |E| = {len(EDGES)} 개 방향성 간선")
    print(f"  인접 행렬 A 는 {len(ids)} x {len(ids)} = {len(ids)**2} 칸")
    print(f"  그중 길이 있는 칸은 {len(ids)**2 - n_inf} 개뿐  "
          f"(밀도 {(len(ids)**2 - n_inf) / len(ids)**2:.1%}) — 아주 희소한 그래프")
    print(f"  입구에서 도달 가능한 노드: {reachable_count(ENTRY)} / {len(NODES)}")

    print()
    print(line)
    print(" 2. 최단경로 (다익스트라)")
    print(line)
    d, prev = dijkstra(ENTRY)
    drive = drive_distances()
    near = min(drive, key=drive.get)
    far = max(drive, key=drive.get)
    print(f"  입구에서 가장 가까운 주차면 : {near}  {drive[near]:6.1f} m")
    print(f"  입구에서 가장 먼   주차면 : {far}  {drive[far]:6.1f} m")
    print(f"  평균 : {sum(drive.values()) / len(drive):.1f} m")
    p = path_of(prev, ENTRY, SLOTS[far]["a"])
    print(f"  가장 먼 자리까지의 경로 ({len(p)} 노드):")
    print(f"    {' -> '.join(p)}")

    print()
    print(line)
    print(" 3. 비용 행렬 C  (주행 + 1.8 x 도보)")
    print(line)
    walk = walk_distances()
    best = min(SLOTS, key=lambda s: W_DRIVE * drive.get(s, 1e9) + W_WALK * walk[s])
    print(f"  가장 싼 자리 : {best}"
          f"  (주행 {drive[best]:.0f} m + 도보 {walk[best]:.0f} m"
          f"  -> 비용 {W_DRIVE*drive[best] + W_WALK*walk[best]:.0f})")
    print(f"  주행만 보면  : {near} (도보는 {walk[near]:.0f} m 로 멉니다)")
    print("  → 두 항이 서로 다른 자리를 가리킵니다. 이 갈등이 문제의 본질입니다.")

    print()
    print(line)
    print(" 4. 배정 : 탐욕법 vs 헝가리안")
    print(line)
    # 차량 8대가 통로 곳곳에 흩어져 있다 (강탈이 일어나 재배정하는 상황)
    car_nodes = ["ENTRY", "H2-04", "H2-11", "H2-18", "H1-16", "H1-08",
                 "H0-03", "H0-14"]
    walk = walk_distances()
    free = sorted(SLOTS, key=lambda s: walk[s])[:20]      # 인기 자리 20개가 비었다

    C = cost_matrix(car_nodes, free)
    gp, gt = greedy_assign(C)
    hp, ht = hungarian(C)

    print(f"  차량 {len(car_nodes)} 대가 통로 곳곳에 흩어져 있고, 빈 자리는 {len(free)} 개")
    print(f"  탐욕법   총비용 = {gt:9.1f}")
    print(f"  헝가리안 총비용 = {ht:9.1f}   ({(ht / gt - 1) * 100:+.2f} %)")
    print()
    print("  배정이 어떻게 갈렸나:")
    print(f"    {'차량 위치':>10}  {'탐욕법':>8}  {'헝가리안':>8}")
    for i, node in enumerate(car_nodes):
        g = free[gp[i]] if gp[i] >= 0 else "-"
        h = free[hp[i]] if hp[i] >= 0 else "-"
        mark = "" if g == h else "   <- 다름"
        print(f"    {node:>10}  {g:>8}  {h:>8}{mark}")
    print()
    print("  → 탐욕법은 앞 차량이 뒤 차량에게 꼭 필요했던 자리를 먼저 가져갑니다.")
    print("     헝가리안은 여덟 대를 한꺼번에 놓고 총합을 최소로 만듭니다.")

    print()
    print(line)
    print(" 5. 혼잡 : 배정이 통로 부하를 바꾼다")
    print(line)
    for label, pick in (("탐욕법", gp), ("헝가리안", hp)):
        routes = []
        for i, j in enumerate(pick):
            if j < 0:
                continue
            _, pv = dijkstra(car_nodes[i])
            pp = path_of(pv, car_nodes[i], SLOTS[free[j]]["a"])
            if pp:
                routes.append(pp)
        st = load_stats(edge_load(routes))
        print(f"  {label:8} 사용 간선 {st['edges']:3d} 개, "
              f"최대 부하 {st['max']} 대, 평균 {st['mean']:.2f} 대")
    print("  → '최대 부하' 가 병목입니다. 총비용이 같아도 병목이 다를 수 있고,")
    print("     그 차이가 곧 혼잡의 차이입니다. 지금 비용 함수에는 이 항이 없습니다.")

    print()
    print(line)
    print(" 생각해볼 것")
    print(line)
    print("  · 비용을 더하기(선형)로 두면 헝가리안으로 최적을 보장받는다.")
    print("    그런데 혼잡은 선형이 아니다 — 차가 두 배면 지연은 두 배가 넘는다.")
    print("    비선형으로 바꾸면 최적 보장을 잃는다. 무엇을 포기할 것인가?")
    print()
    print("  · 차량은 한꺼번에 오지 않고 하나씩 온다. 미래를 모르는 채로")
    print("    지금 결정해야 한다 (온라인 문제). 최적과 얼마나 벌어지는가?")
    print()
    print("  · 자리는 무작위로 비워진다. '지금 이 자리를 주면 나중에 곤란해지는가'")
    print("    를 비용에 넣으려면 확률을 다뤄야 한다.")


if __name__ == "__main__":
    main()
